import { useMemo, useState } from 'react';

// Разметка построена на CSS-first примитивах jx-* (packages/core), без угадывания
// экспортов @jinx-ui/react — сверь имена классов/токенов с пакетом core/tokens.

const PAGE_SIZE = 10;

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string | number;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
  caption?: string;
}

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_CLASS: Record<UserStatus, string> = {
  active: 'jx-badge jx-badge--success',
  disabled: 'jx-badge jx-badge--muted',
};

export default function UsersTable({ users, caption = 'Пользователи' }: UsersTableProps) {
  const [requestedPage, setRequestedPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const page = Math.min(Math.max(requestedPage, 1), pageCount);

  const rows = useMemo(
    () => users.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE),
    [users, page],
  );

  const pages = useMemo(
    () => Array.from({ length: pageCount }, (_, index) => index + 1),
    [pageCount],
  );

  return (
    <section className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <table className="jx-table">
        <caption className="jx-table__caption">{caption}</caption>
        <thead className="jx-table__head">
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody className="jx-table__body">
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-table__empty">
                Нет пользователей
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id} className="jx-table__row">
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span className={STATUS_CLASS[user.status]}>
                    {STATUS_LABEL[user.status]}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Постраничная навигация"
        style={{ gap: 'var(--jx-space-2)', alignItems: 'center' }}
      >
        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          onClick={() => setRequestedPage(page - 1)}
          disabled={page <= 1}
        >
          Назад
        </button>

        {pages.map((pageNumber) => (
          <button
            key={pageNumber}
            type="button"
            className={
              pageNumber === page ? 'jx-btn jx-btn--primary' : 'jx-btn jx-btn--ghost'
            }
            aria-current={pageNumber === page ? 'page' : undefined}
            aria-label={`Страница ${pageNumber}`}
            onClick={() => setRequestedPage(pageNumber)}
          >
            {pageNumber}
          </button>
        ))}

        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          onClick={() => setRequestedPage(page + 1)}
          disabled={page >= pageCount}
        >
          Вперёд
        </button>

        <span className="jx-text jx-text--muted" aria-live="polite">
          {`Страница ${page} из ${pageCount}`}
        </span>
      </nav>
    </section>
  );
}

